const DICT: Record<string, D> = { pt, en, ru };

export function t(key: string, p?: Record<string, any>): string {
  const lang = getSettings().lang;
  let s = DICT[lang]?.[key] ?? en[key] ?? pt[key] ?? key;
  if (p) for (const k of Object.keys(p)) s = s.split('{' + k + '}').join(String(p[k]));
  return s;
}
export function keyLabel(code: string): string {
  const k = t('key.' + code); if (k !== 'key.' + code) return k;
  if (code.startsWith('Key')) return code.slice(3); if (code.startsWith('Digit')) return code.slice(5);
  return code.replace('Arrow', '↔ ').replace('Left', ' L').replace('Right', ' R');
}
